use vstd::prelude::*;

verus! {

fn linear_search(nums: Vec<i32>, target: i32) -> (res: i32)
    requires
        // So that any found index can be returned as i32 safely.
        nums.len() <= i32::MAX as usize,
    ensures
        // If we return -1, then target does not occur in the vector.
        res == -1 ==> forall|j: int|
            0 <= j < nums.len() ==> nums[j] != target,
        // If we return an index, it is in-bounds and points to an occurrence.
        res != -1 ==> 0 <= res < nums.len() as i32,
        res != -1 ==> nums[res as int] == target,
        // If we return an index, it is the first occurrence.
        res != -1 ==> forall|j: int|
            0 <= j < res as int ==> nums[j] != target,
{
    for (i, &v) in nums.iter().enumerate()
        invariant
            // enumerate index always stays within 0..=len
            i <= nums.len(),
            // all prior elements are not the target (otherwise we would have returned)
            forall|j: int| 0 <= j < i ==> nums[j] != target,
        decreases nums.len() - i
    {
        if v == target {
            // Help the prover relate `v` (from the iterator) to `nums[i]`.
            assert(nums[i as int] == v);

            // From the loop invariant, we also have minimality.
            return i as i32;
        }
    }
    -1
}

} // verus!